eval("/**\n * @file dcp-client/worker/supervisor2/job-manager.js\n *\n * A support class for Supervisor2.\n * It is a wrapper for the job object returned from the requestTask,\n * along with tracking slices and sandboxes associated with the job. \n *\n * @author Wes Garland, wes@distributive.network,\n *         Paul, paul@distributive.network,\n * @date Dec 2020,\n *       June 2022, Jan-April 2023\n * @module job-manager\n * @copyright Copyright (c) 2018-2024, Distributive Corp. All Rights Reserved\n */\n// @ts-check\n\n\n// Turn on to see how metrics grow with time.\nconst displayStatHistory = false;\n\n/** @typedef {string} opaqueId */ // 22 character base64 string\n/** @typedef {string} address  */ // String(Address)\n/** @typedef {import('./sandbox2').Sandbox} Sandbox                      */\n/** @typedef {import('./sandbox2').SandboxHandle} SandboxHandle          */\n/** @typedef {import('./index').Supervisor} Supervisor                   */\n/** @typedef {import('dcp/utils/jsdoc-types').SliceMessage} SliceMessage */\n/** @typedef {import('dcp/utils/jsdoc-types').Auth} Auth                 */\n/** @typedef {import('dcp/utils/jsdoc-types').Signature} Signature       */\n/** @typedef {import('dcp/utils/jsdoc-types').AuthMessage} AuthMessage   */\n/** @typedef {import('dcp/dcp-client/worker/origin-access-manager').OriginAccessManager} OriginAccessManager */\n\nconst { assert } = __webpack_require__(/*! dcp/common/dcp-assert */ \"./src/common/dcp-assert.js\");\nconst inspect = Symbol.for('nodejs.util.inspect.custom');\nconst debugging = (__webpack_require__(/*! dcp/debugging */ \"./src/debugging.js\").scope)('worker');\nconst EventEmitter = __webpack_require__(/*! events */ \"./node_modules/events/events.js\");\nconst { Inventory } = __webpack_require__(/*! dcp/utils/inventory */ \"./src/utils/inventory.js\");\nconst { Synchronizer } = __webpack_require__(/*! dcp/common/concurrency */ \"./src/common/concurrency.js\");\nconst { rehydrateRange } = __webpack_require__(/*! dcp/dcp-client/range-object */ \"./src/dcp-client/range-object.js\");\nconst { fetchURIAndLength } = __webpack_require__(/*! dcp/utils/fetch-uri */ \"./src/utils/fetch-uri.js\");\nconst utils = __webpack_require__(/*! dcp/utils */ \"./src/utils/index.js\");\nconst { stringify, a$sleepMs } = utils;\nconst wd = __webpack_require__(/*! dcp/utils/worker-and-daemons */ \"./src/utils/worker-and-daemons.js\");\nconst { allowOriginsPurposes } = __webpack_require__(/*! dcp/common/worker-constants */ \"./src/common/worker-constants.js\");\n\nconst { Slice } = __webpack_require__(/*! ./slice2 */ \"./src/dcp-client/worker/supervisor2/slice2.js\");\nconst { Promise_any } = __webpack_require__(/*! ./promise_any */ \"./src/dcp-client/worker/supervisor2/promise_any.js\");\nconst { SandboxError, UncaughtExceptionError } = __webpack_require__(/*! ./sandbox2 */ \"./src/dcp-client/worker/supervisor2/sandbox2.js\");\nconst { updateGPUStatistics } = __webpack_require__(/*! ./gpu_support */ \"./src/dcp-client/worker/supervisor2/gpu_support.js\");\nconst common = __webpack_require__(/*! ./common */ \"./src/dcp-client/worker/supervisor2/common.js\");\nconst { selectiveDebug, selectiveDebug2, debugBuild, selectiveSupEx } = common;\n\nconst INITIAL = 'initial';\nconst READY   = 'ready';\nconst STOP    = 'stop';\nconst REFUSE  = 'refuse';\nconst BROKEN  = 'broken';\nconst DEAD    = 'dead'; // supervisior.purgeJob(this) has been called\n\nclass BadOriginError   extends SandboxError { constructor(msg) { super('EPERM_ORIGIN', msg); } }\nclass RemoteFetchError extends SandboxError { constructor(msg) { super('EFETCH',       msg); } }\n\n/**\n * Public event emitter.\n * https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md\n */\nclass JobHandle extends EventEmitter\n{\n  /** @type {JobManager} */\n  #jobManager;\n  \n  /**\n   * @constructor\n   * @param {JobManager} jobManager\n   */\n  constructor (jobManager)\n  {\n    super({ captureRejections: false });\n    this.#jobManager = jobManager;\n  }\n  /** @type {string} */\n  get address ()     { return this.#jobManager.address; }\n  /** @type {string} */\n  get name ()        { return this.#jobManager.public?.name ?? '<unknown>'; }\n  /** @type {string} */\n  get description () { return this.#jobManager.public?.description ?? '<unknown>'; }\n  /** @type {string} */\n  get link ()        { return this.#jobManager.public?.link ?? '<unknown>'; }\n  /** @type {boolean} */\n  get estimation ()  { return this.#jobManager.isEstimation; }\n}\nexports.JobHandle = JobHandle;\n\n//\n// Index to functionality -- search for '_Idx' to toggle through the index.\n//\n// 1)  class JobManager\n// 2)  addSlices, fetchDependencies, updateStatistics, update, predictLoad\n// 3)  reserveOneSlice, resetSlices, destroy, evaluatorDownCleanup\n// 4)  assignSandbox, runSlice, runSliceOnSandbox\n// 5)  removeSlice\n// 6)  fetchError, fetchJob, fetchSliceData\n// 7)  jobEmit, sandboxEmit, error, warning. countSliceStr, dumpSlices.\n//\n\n// _Idx\n//\n// class JobManager\n// A JobManager handles all scheduling of slices for a given job.\n// It's also responsible for fetching slice data, work functions and arguments.\n// And it collects statistics about slice completion times and resource usage.\n// All functionality across jobs is handled by Supervisor.\n//\n\n/**\n * JobManager Constructor. An instance of JobManager knows everything about a given\n * job within the supervisor, including:\n *  - work function code\n *  - work function arguments\n *  - all the SliceManager instances that go with this job\n *  - how long a slice of this job is expected to run\n *\n * Instances of JobManager emit the following events:\n *  - addSlice(sliceHandle)\n *  - deleteSlice(sliceHandle)\n *  - statusChange(new state, old state);\n *\n * JobManager States\n *\n * Start state:\n * initial\n *\n * Intermediate states:\n * ready\n *\n * Terminal states:\n * broken - job could not be initialized\n * refuse - for some reason, we have decided that we don't want work for this job\n * stop   - job manager has been stopped\n *\n * Valid transitions:\n * initial  -> broken\n * initial  -> ready\n * initial  -> ready -> stop\n * anything -> dead\n * \n * NOTE: If you ever use a property with a leading underscore you are probably making a mistake.\n *       But if you must, please ask paul, yarn, bryan or eddie for a CR.\n */\nclass JobManager\n{\n  /** @type {Supervisor} */\n  #supervisor;\n  /** @type {Slice[]} */\n  #sliceInventory;\n  /** @type {Synchronizer} */\n  #state;\n  /** @type {*} */ // Figure out the type\n  #jobMessage;\n  /** @type {string} */\n  #address;\n  /** @type {Promise<*>} */\n  #jobPromise;\n\n  /**\n   * @constructor\n   * @param {Supervisor}     parent               - Owning Supervisor.\n   * @param {object}         jobMessage           - Job Descriptor from getJobsForTask.\n   * @param {SliceMessage[]} sliceMessages        - Messages from task distributor describing slices.\n   * @param {AuthMessage}    authorizationMessage - The signature that shipped with the task authorizing this worker.\n   */\n  constructor(parent, jobMessage, sliceMessages, authorizationMessage)\n  {\n    this.#supervisor = parent;\n    this.#sliceInventory = []; // All slices for this.address.\n    this.#state = new Synchronizer(INITIAL, [ INITIAL, READY, STOP, REFUSE, BROKEN, DEAD ]);\n    this.#jobMessage = { ...jobMessage };\n    this.#address = String(this.jobMessage.address);\n    this.#jobPromise = null;\n\n    /** @type {{CPUTime: number, GPUTime: number, ElapsedTime: number, CPUDensity: number, GPUDensity: number, CPUTime_variance: number, GPUTime_variance: number }} */\n    this.localMetrics = null;\n    /** @type {Array<{slice: number, reason: string|boolean}>} */\n    this.rejectedJobReasons = [];\n    /** @type {boolean} */\n    this.isEstimation = true;\n    /** @type {boolean} */\n    this.isLong = false;\n    /** @type {number} */\n    this.inputDataSize = 0;\n\n    /*\n     * Make sure this.metrics contains valid data.\n     * With old legacy schedulers, this may not be so.\n     */\n    this.fixUpMetrics();\n\n    if (displayStatHistory)\n    {\n      this.CPUHistory = [];\n      this.CPUVarHistory = [];\n    }\n\n    /** \n     * Start loading dependencies in the background. Once these are loaded, this.state will\n     * transition to 'ready' and the job will be ready for work. Do not place this job manager\n     * in inventory until 'ready'.\n     */\n    this.#jobPromise = this.fetchDependencies(sliceMessages, authorizationMessage)\n      .then(() => {\n        this.supervisor.jobManagerInventory.push(this);\n        if (!common.removeElement(this.supervisor.unresolvedJobs, this.address) && debugBuild)\n          this.warning(`Cannot find address ${this.address} in unresolvedJobs ${JSON.stringify(this.supervisor.unresolvedJobs, null, 2)}`);\n      });\n\n    /* Check for GPU support. */\n    const _env = this.requirements?.environment;\n    /** @type {boolean} */\n    this.useGPU = _env ? (_env.webgpu || _env.offscreenCanvas) : false;\n    \n    /**\n     * Event emitter containing info that describes the job.\n     * @type {JobHandle}\n     */\n    this.jobHandle = new JobHandle(this);\n\n    /**\n     * Emit the 'job' event on the worker event emitter.\n     */\n    this.supervisor.safeEmit(this.supervisor.worker, 'job', this.jobHandle);\n  }\n\n  /** @type {*} */  // Figure out the type\n  get jobMessage ()    { return this.#jobMessage; }\n  /** @type {string} */\n  get address ()       { return this.#address;  }\n  /** @type {string} */\n  get uuid ()          { return this.jobMessage.uuid; }\n  /** @type {boolean} */\n  get workerConsole () { return this.jobMessage.workerConsole; }\n  /** @type {object} */\n  get requirements ()  { return this.jobMessage.requirements; }\n  /** @type {boolean} */\n  get almostDone ()    { return this.jobMessage.almostDone; }\n\n  // These 3 properties have type object.\n  get mro ()          { return this.jobMessage.mro; }\n  get arguments ()    { return this.jobMessage.arguments; }\n  get workFunction () { return this.jobMessage.workFunction; }\n\n  /** @type {{computeGroups: Array<{opaqueId: string, name: string, description: string}>, name: string, description: string, link: string}} */\n  get public ()       { return this.jobMessage.public; }\n  /** @type {{sliceCPUTime: number, sliceGPUTime: number, sliceCPUDensity: number, sliceGPUDensity: number, lastSliceNumber: number, measuredSlices: number, alpha: number}} */\n  get metrics ()      { return this.jobMessage.metrics; }\n  /** @type {Supervisor} */\n  get supervisor ()   { return this.#supervisor; }\n  /** @type {Synchronizer} */\n  get state ()        { return this.#state; }\n\n  /** @type {boolean} */\n  get ready ()        { return this.state.is(READY); }\n  /** @type {boolean} */\n  get dead ()         { return this.state.is(DEAD); }\n\n  // These 4 aren't needed yet.\n  ///** @type {boolean} */\n  //get initial () { return this.state.is(INITIAL); }\n  ///** @type {boolean} */\n  //get stopped () { return this.state.is(STOP); }\n  ///** @type {boolean} */\n  //get refuse ()  { return this.state.is(REFUSE); }\n  ///** @type {boolean} */\n  //get broken ()  { return this.state.is(BROKEN); }\n\n  /** @type {Sandbox[]} */\n  get sandboxInventory ()  { return this.supervisor.sandboxInventory.filter((sandbox) => sandbox.jobAddress === this.#address && !sandbox.isTerminated); }\n  /** @type {Sandbox[]} */\n  get assignedSandboxes () { return this.supervisor.sandboxInventory.filter((sandbox) => sandbox.jobAddress === this.#address && sandbox.isAssigned); }\n  /** @type {Sandbox[]} */\n  get workingSandboxes ()  { return this.supervisor.sandboxInventory.filter((sandbox) => sandbox.jobAddress === this.#address && sandbox.isWorking); }\n  /** @type {Slice[]} */\n  get sliceInventory ()    { return this.#sliceInventory; }\n  /** @type {Slice[]} */\n  get readySlices ()       { return this.sliceInventory.filter((slice) => slice.isReady); }\n  /** @type {Slice[]} */\n  get queuedSlices ()      { return this.sliceInventory.filter((slice) => slice.isQueued); } // Ready and soon-to-be-ready\n  /** @type {Slice[]} */\n  get reservedSlices ()    { return this.sliceInventory.filter((slice) => slice.isReserved); }\n  /** @type {Slice[]} */\n  get activeSlices ()      { return this.sliceInventory.filter((slice) => slice.isActive); } // Reserved, working, workdone and complete\n  /** @type {Slice[]} */\n  get workingSlices ()     { return this.sliceInventory.filter((slice) => slice.isWorking || slice.isReserved); } // Working and soon-to-be-working\n  /** @type {Slice[]} */\n  get unFinishedSlices ()  { return this.sliceInventory.filter((slice) => !slice.isFinished); }\n\n  /** @type {number} */\n  get sliceMultiplier () { return this.supervisor.options.sliceMultiplier; }\n  /** @type {number} */\n  get sliceSigmas ()     { return this.supervisor.options.sliceSigmas; }\n  /** @type {number} */\n  get sliceBiasMs ()  { return this.supervisor.options.sliceBiasMs; }\n  /** @type {number} */\n  get lifetimeFactor ()  { return this.supervisor.options.lifetimeFactor; }\n\n  /** @type {Promise<*>} */\n  get jobPromise ()   { return this.#jobPromise; }\n  /** @type {number} */\n  get defaultQuanta () { return this.isEstimation ? 1.0 : this.supervisor.quanta.defaultQuanta; }\n  /** @type {number} */\n  get globalTime ()   { return wd.globalTime(this.metrics);  }\n  /** @type {number} */\n  get globalTimeFixedUp () { return this.globalTime || this.supervisor.options.targetTaskDurationMs;  }\n  /** @type {number} */\n  get globalElapsedTime () { return wd.globalElapsedTime(this.metrics) || this.supervisor.options.targetTaskDurationMs;  }\n  /** @type {number} */\n  get emaSliceTime () { return wd.localTime(this.localMetrics) || (this.globalTimeFixedUp * this.defaultQuanta); }\n  /** @type {number} */\n  get emaElapsedTime () { return this.localMetrics?.ElapsedTime || (this.globalElapsedTime * this.defaultQuanta); }\n  /** @type {number} */\n  get adjSliceTime () { return Math.min(this.emaSliceTime, this.supervisor.options.targetTaskDurationMs); }\n  /** @type {string} */\n  get identifier ()   { return `${common.truncateAddress(this.address)}.${this.state}`; }\n  /** @type {string} */\n  get sliceState ()   { return `${this.queuedSlices.length}.${this.workingSliceCount}.${this.sliceInventory.length}.${this.workRemaining}`; }\n  /** @type {string} */\n  get [inspect] ()    { return `[Object JobManager <${this.public.name}::${common.truncateAddress(this.address)}::${this.state}>]`; }\n  /** @type {OriginAccessManager} */\n  get originManager() { return this.supervisor.originManager; }\n  /**\n   * Expected density of a slice.\n   * @type {number}\n   */\n  get estimateDensity () { return this.localMetrics?.CPUDensity || wd.globalDensity(this.metrics); }\n  /** @type {number} */\n  get estimateGPUDensity () { return this.localMetrics?.GPUDensity || wd.globalGPUDensity(this.metrics); }\n  /**\n   * Estimate the number of milliseconds of total execution time of the job.\n   * @type {number}\n   */\n  get workRemaining ()\n  {\n    const _adjSliceTime = this.adjSliceTime;\n    const queuedTime = _adjSliceTime * this.queuedSlices.length;\n    let workingTime = 0;\n    for (const slice of this.workingSlices)\n    {\n      workingTime += Math.max(0, _adjSliceTime - (Date.now() - slice.startTime));\n      selectiveDebug2() && console.debug(`JobManager.workRemaining: _adjSliceTime ${_adjSliceTime}, slice-time-elapsed ${Date.now() - slice.startTime}`);\n    }\n    selectiveDebug() && console.debug(`JobManager.workRemaining: queuedTime ${queuedTime}, queuedCount ${this.queuedSlices.length}, workingTime ${workingTime}, workingCount ${this.workingSliceCount}`);\n    return workingTime + queuedTime;\n  }\n  /**\n   * Are there no working slices?\n   * @type {boolean}\n   */\n  get isNotWorking ()\n  {\n    for (const slice of this.sliceInventory)\n      if (slice.isReserved || slice.isWorking)\n        return false;\n    return true;\n  }\n  /**\n   * Estimated count of working (or reserved) slices.\n   * @type {number}\n   */\n  get workingSliceCount ()\n  {\n    let count = 0;\n    for (const slice of this.sliceInventory)\n      if (slice.isReserved || slice.isWorking)\n        ++count;\n    return count;\n  }\n  /**\n   * Estimated density of working (or reserved) slices.\n   * @type {number}\n   */\n  get workingSliceDensity () { return this.workingSliceCount * this.estimateDensity;  }\n  /**\n   * Estimated density of working (or reserved) slices.\n   * @type {number}\n   */\n  get workingGPUDensity () { assert(this.useGPU); return this.workingSliceCount * this.estimateGPUDensity;  }\n  /**\n   * Create array of sliceNumbers from all unfinished slices.\n   * @type {number[]}\n   */\n  get sliceNumbers ()\n  {\n    const result = [];\n    for (const slice of this.sliceInventory)\n      if (!slice.isFinished)\n        result.push(slice.sliceNumber);\n    return result;\n  }\n  /**\n   * Always display max info under debug builds, otherwise maximal error\n   * messages are displayed to the worker, only if both worker and client agree.\n   * When displayMaxDiagInfo is true, display stack trace and other enhanced diag info.\n   * @type {boolean}\n   **/\n  get displayMaxDiagInfo ()\n  {\n    return common.displayMaxDiagInfo() || this.workerConsole && this.supervisor.options.allowConsoleAccess;\n  }\n\n  // _Idx\n  //\n  // addSlices, fetchDependencies, updateStatistics, update, predictLoad\n  //\n\n  /**\n   * Add slices to the job manager's inventory.\n   *\n   * @param {SliceMessage[]} sliceMessages        - Messages from task distributor describing slices.\n   * @param {AuthMessage}    authorizationMessage - The signature that shipped with the task authorizing this worker.\n   * @returns {Promise<*>}\n   */\n  addSlices (sliceMessages, authorizationMessage)\n  {\n    /** @type {Array<Promise<void>>} */\n    const slicePromises = [];\n    sliceMessages.forEach((sliceMessage) => {\n      const slice = new Slice(this, sliceMessage, authorizationMessage);\n      selectiveDebug2() && console.debug(`JobManager.addSlices: worker ${this.supervisor.workerId}, slice ${slice.identifier}, isEstimation ${slice.isEstimation}, isLong ${slice.isLong}`);\n      /** XXXpfr @todo Make isEstimation and isLong part of the jobMessage from getJobsForTask in task-jobs.js  */\n      if (!slice.isEstimation)\n        this.isEstimation = false;\n      if (slice.isLong)\n        this.isLong = true;\n      this.sliceInventory.push(slice);\n      slicePromises.push(slice.fetchSliceDataPromise);\n    });\n    return Promise_any(slicePromises);\n  }\n\n  /**\n   * Fetch dependencies.\n   * @param {SliceMessage[]} sliceMessages        - Messages from task distributor describing slices.\n   * @param {AuthMessage}    authorizationMessage - The signature that shipped with the task authorizing this worker.\n   * @returns {Promise<*>}\n   */\n  async fetchDependencies (sliceMessages, authorizationMessage)\n  {\n    return this.fetchJob(this.jobMessage)\n      .then (() => {\n        debugging('supervisor') && console.debug('JobManager is transitioning to READY', this.identifier, Date.now() - this.supervisor.lastTime);\n        this.state.set(INITIAL, READY);\n        return this.addSlices(sliceMessages, authorizationMessage);\n      }, (error) => {\n        selectiveDebug() && console.error('fetchJob has failed', error);\n        this.state.set(INITIAL, BROKEN);\n\n        // Insert all slices to the sliceInventory without downloading their data, so that\n        // JobManager.destroy will return slices to scheduler.\n        sliceMessages.forEach((sliceMessage) => {\n          const slice = new Slice(this, sliceMessage, authorizationMessage, false);\n          this.sliceInventory.push(slice);\n        });\n        // Clean up this jobManager instance, and reject the job\n        this.supervisor.purgeJob(this);\n        this.supervisor.ringBufferOfRejects.push(this.address);\n        throw error;\n      });\n  }\n\n  /**\n   * Assume slice is in state WORKDONE.\n   * Create a READY clonedSlice with the necessary properties from slice.\n   * Used in handleWorkReject.\n   * @param {Slice} slice\n   */\n  cloneSlice (slice)\n  {\n    if (!slice.isWorkDone)\n      throw new Error(`Can only clone a slice in state WORKDONE; slice is in state ${slice.state}`);\n    // Clone a READY slice.\n    const clonedSlice = slice.cloneReady();\n    // Take the original slice out of play.\n    common.removeElement(this.sliceInventory, slice);\n    // Place it in inventory.\n    this.sliceInventory.push(clonedSlice);\n  }\n\n  /** XXXpfr @todo Factor out statistics and EMA into another class. */\n  /**\n   * @param {number} x\n   * @param {boolean} [isDensity]\n   * @returns {boolean}\n   */\n  static isValid (x, isDensity = false)\n  {\n    return Number.isFinite(x) && !(x < 0) && !(isDensity && x > 1);\n  }\n\n  /**\n   * Old legacy DCP schedulers can send a corrupt this.metrics .\n   * We should get rid of this when we don't support old legacy DCP schedulers.\n   */\n  fixUpMetrics ()\n  {\n    if (!this.metrics)\n      this.jobMessage.metrics = { sliceCPUTime: 0, sliceCPUDensity: 1, sliceGPUTime: 0, sliceGPUDensity: 0 }; // sliceInDataSize: 0, sliceOutDataSize: 0 };\n    else\n    {\n      if (!(JobManager.isValid(this.metrics.sliceCPUTime) && JobManager.isValid(this.metrics.sliceCPUDensity, true)))\n      {\n        this.metrics.sliceCPUTime = 1;\n        this.metrics.sliceCPUDensity = 0.5;\n      }\n      if (!(JobManager.isValid(this.metrics.sliceGPUTime) && JobManager.isValid(this.metrics.sliceGPUDensity, true)))\n      {\n        this.metrics.sliceGPUTime = 1;\n        this.metrics.sliceGPUDensity = 0.5;\n      }\n      // if (!JobManager.isValid(this.metrics.sliceInDataSize))  -- Not used yet\n      //   this.metrics.sliceInDataSize = 0;\n      // if (!JobManager.isValid(this.metrics.sliceOutDataSize)) -- Not used yet\n      //   this.metrics.sliceOutDataSize = 0;\n    }\n  }\n\n  /**\n   * @param {Slice}         slice\n   * @param {SandboxHandle} sandboxHandle\n   * @returns {{CPUTime: number, GPUTime: number, CPUDensity: number, GPUDensity: number, InDataSize: number, OutDataSize: number}}\n   */\n  updateStatistics (slice, sandboxHandle)\n  {\n    /**\n     * @param {{CPUTime: number, GPUTime: number, CPUDensity: number, GPUDensity: number, InDataSize: number, OutDataSize: number}} metrics\n     * @returns {boolean}\n     */\n    const isValidMetrics = (metrics) => {\n      return !debugBuild // Only check when debugBuild.\n        || (JobManager.isValid(metrics.CPUTime) && JobManager.isValid(metrics.CPUDensity, true)\n        && JobManager.isValid(metrics.GPUTime) && JobManager.isValid(metrics.GPUDensity, true)\n        && JobManager.isValid(metrics.InDataSize) && JobManager.isValid(metrics.OutDataSize));\n    }\n    /** @returns {boolean} */\n    const isValidLocalMetrics = () => {\n      return !debugBuild // Only check when debugBuild.\n        || (JobManager.isValid(this.localMetrics.CPUTime) && JobManager.isValid(this.localMetrics.CPUDensity, true)\n        && JobManager.isValid(this.localMetrics.GPUTime) && JobManager.isValid(this.localMetrics.GPUDensity, true)\n        && JobManager.isValid(this.localMetrics.CPUTime_variance) && JobManager.isValid(this.localMetrics.GPUTime_variance));\n    }\n\n    const timeReport = slice.timeReport;\n    const dataReport = slice.dataReport;\n    selectiveDebug() && console.debug('updateStatistics', slice.identifier, timeReport, dataReport);\n\n    // Sanity\n    if (!(timeReport.CPU >= 1))\n    {\n      timeReport.CPU = 1;\n      timeReport.total += 1;\n    }\n    if (!(timeReport.total >= 1))\n      timeReport.total = 1;\n\n    // Construct metrics.\n    const GPUTime = timeReport.webGPU + timeReport.webGL;\n    if (this.useGPU)\n      updateGPUStatistics(GPUTime);\n    const metrics = {\n      CPUTime:     timeReport.CPU,\n      GPUTime,\n      CPUDensity:  timeReport.CPU / timeReport.total,\n      GPUDensity:  GPUTime / timeReport.total,\n      InDataSize:  dataReport.InDataSize,\n      OutDataSize: dataReport.OutDataSize,\n    };\n\n    // Create the measurement object which will be passed to the metrics event.\n    const eventMeasurements = {\n      elapsed: timeReport.total / 1000,\n      CPU:     metrics.CPUTime / 1000,\n      GPU:     metrics.GPUTime / 1000,\n      in:      metrics.InDataSize,\n      out:     metrics.OutDataSize,\n    };\n\n    // Emit metrics event for both jobHandle and sandboxHandle\n    this.jobEmit(             'metrics', slice.sliceNumber, eventMeasurements);\n    this.sandboxEmit(sandboxHandle, 'metrics', slice.sliceNumber, eventMeasurements);\n    // The sliceEnd event fires immediately after the metrics event.\n    this.sandboxEmit(sandboxHandle, 'sliceEnd',slice.sliceNumber);\n    selectiveDebug() && console.debug(`updateStatistics: slice ${slice.identifier}, eventMeasurements ${stringify(eventMeasurements)}`);\n\n    if (!isValidMetrics(metrics))\n      throw new Error(`JobManager.updateStatistics: metrics are in an inconsistent state ${JSON.stringify(metrics, null, 2)}`);\n\n    if (!this.localMetrics)\n      this.localMetrics = { CPUTime: 0, GPUTime: 0, ElapsedTime: 0, CPUDensity: 0, GPUDensity: 0, CPUTime_variance: null, GPUTime_variance: null };\n\n    // measuredSlices+1 because the current slice hasn't been measured yet in RS.updateMetrics.\n    const alpha = this.metrics?.lastSliceNumber\n      ? wd.constructAlpha(this.metrics.lastSliceNumber, this.metrics.measuredSlices + 1)\n      : 0.5;\n    selectiveDebug2() && console.debug(`updateStatistics: local alpha ${alpha}, global alpha ${this.metrics?.alpha}`);\n\n    //\n    // How to create EMA and EMVAR series from x[i], i = 0, 1, 2, ...\n    // delta[i] <- x[i] - ema[i-1]\n    // ema[i] <- ema[i-1] + alpha * delta[i]: ema[0] = x[0]\n    // emvar[i] <- (1-alpha) * (emvar[i-1] + alpha * delta[i]^2): emvar[0] = 0\n    //\n    // Note: Must calculate this.localMetrics.CPUTime_variance first because\n    //  this.localMetrics.CPUTime must be the previous value, not the current value.\n    //  Similarly for this.localMetrics.GPUTime_variance.\n    //\n\n    this.localMetrics.CPUTime_variance = wd.nextEmvar(this.localMetrics.CPUTime_variance, this.localMetrics.CPUTime, metrics.CPUTime, alpha);\n    this.localMetrics.GPUTime_variance = wd.nextEmvar(this.localMetrics.GPUTime_variance, this.localMetrics.GPUTime, metrics.GPUTime, alpha);\n    this.localMetrics.CPUTime     = wd.nextEma(this.localMetrics.CPUTime,    metrics.CPUTime, alpha);\n    this.localMetrics.GPUTime     = wd.nextEma(this.localMetrics.GPUTime,    metrics.GPUTime, alpha);\n    this.localMetrics.ElapsedTime = wd.nextEma(this.localMetrics.ElapsedTime,  timeReport.total, alpha);\n    this.localMetrics.CPUDensity  = wd.nextEma(this.localMetrics.CPUDensity, metrics.CPUDensity, alpha);\n    this.localMetrics.GPUDensity  = wd.nextEma(this.localMetrics.GPUDensity, metrics.GPUDensity, alpha);\n    //this.localMetrics.InDataSize  = wd.nextEma(this.localMetrics.InDataSize, metrics.InDataSize, alpha);   -- Not used yet\n    //this.localMetrics.OutDataSize = wd.nextEma(this.localMetrics.OutDataSize, metrics.OutDataSize, alpha); -- Not used yet\n\n    if (displayStatHistory)\n    {\n      this.CPUHistory.push(this.localMetrics.CPUTime.toFixed(2));\n      this.CPUVarHistory.push(Math.sqrt(this.localMetrics.CPUTime_variance).toFixed(3));\n      console.log('CPUHistory', this.CPUHistory);\n      console.log('CPUVarHistory', this.CPUVarHistory);\n    }\n\n    if (common.debugQuanta())\n    {\n      this.supervisor.dbg.addRawLocal(slice, metrics, alpha);\n      this.supervisor.dbg.addLocal(slice, this.emaSliceTime, alpha);\n    }\n\n    if (!isValidLocalMetrics())\n      throw new Error(`JobManager.updateStatistics: localMetrics are in an inconsistent state ${JSON.stringify(this.localMetrics, null, 2)}`);\n\n    debugging('supervisor') && console.debug('updateStatistics: emaSliceTime', this.emaSliceTime, 'estimateDensity', this.estimateDensity, 'alpha', alpha, 'metrics', metrics, 'g-metrics', this.metrics, 'l-metrics', this.localMetrics);\n    return metrics;\n  }\n\n  /**\n   * Calculate the overdue threshold for current job.\n   * Does not apply to jobs in estimation.\n   * @returns {number}\n   */\n  computeOverdueThreshold ()\n  {\n    selectiveDebug2() && console.debug(`computeOverdueThreshold(${this.identifier},${this.#supervisor.workerId})`, this.isEstimation, this.#supervisor.options.useLifetimeAnalysis, this.#supervisor.options.soteriaFrequencyMs);\n    //this.supervisor.showSlices('JM.computeOverdueThreshold');\n    if (this.isEstimation)\n      return -1;\n    const totalTime = this.emaElapsedTime;\n    const totalVariance = wd.localElapsedVariance(this.localMetrics);\n    // stddev is constrained:  stddev >= 0.125 * totalTime\n    const stddev = Math.max(Math.sqrt(totalVariance), 0.125 * totalTime);\n    // roughly Gaussian with mean = totalTime and stddev = soteriaConfig.sliceSigmas.\n    const estimatedTime = totalTime + this.sliceSigmas * stddev;\n    const threshold = this.sliceBiasMs + this.sliceMultiplier * estimatedTime;\n    selectiveSupEx() && console.debug(`computeOverdueThreshold(${this.identifier},${this.#supervisor.workerId}): threshold=${threshold * this.lifetimeFactor}/${threshold}/${this.lifetimeFactor}`, this.#supervisor.options.soteriaFrequencyMs);\n\n    return threshold * this.lifetimeFactor;\n  }\n\n  /**\n   * Update jobMessage, add some slices to inventory.\n   * @param {object}         jobMessage             - Job Descriptor from getJobsForTask.\n   * @param {SliceMessage[]} [sliceMessages]        - Messages from task distributor describing slices.\n   * @param {AuthMessage}    [authorizationMessage] - The signature that shipped with the task authorizing this worker.\n   * @returns {Promise<*>}\n   */\n  update (jobMessage, sliceMessages, authorizationMessage)\n  {\n    Object.assign(this.jobMessage, jobMessage);\n    /*\n     * Make sure this.metrics contains valid data.\n     * With old legacy schedulers, this may not be so.\n     */\n    this.fixUpMetrics();\n    selectiveDebug2() && console.debug('JM.update: new this.jobMessage', this.jobMessage.metrics);\n\n    if (sliceMessages)\n      return (this.#jobPromise = this.addSlices(sliceMessages, authorizationMessage));\n  }\n\n  /**\n   * Predict the total reduction in density of working sandboxes timeSpanMs from now.\n   * This function is called right before fetchTask, in order to calculate how much space is available.\n   * In pratice, the returned property queued will have length <= 1, because when it is more we won't call fetchWork.\n   * @param {number} timeSpanMs\n   * @returns {{ queued: Slice[], working: number }}\n   */\n  predictLoad (timeSpanMs)\n  {\n    const queuedSlices = this.queuedSlices;\n    const workingSliceCount = this.workingSliceCount;\n    const estimateDensity = this.estimateDensity;\n    const emaSliceTime = this.emaSliceTime;\n    let queuedCount = queuedSlices.length;\n    selectiveDebug() && console.debug(`JM.predictLoad(${timeSpanMs}): queued ${queuedCount}, workingSliceCount ${workingSliceCount}, density ${estimateDensity}, sliceTime ${emaSliceTime}, estimation ${this.isEstimation}, long ${this.isLong}`);\n\n    // Optimize to short-circuit when queued > 1, because we won't call fetchWork in that case.\n    if (queuedCount > workingSliceCount + 1)\n    {\n      selectiveDebug() && console.debug(`JM.predictLoad: bail early:`, queuedCount, workingSliceCount);\n      return { queued: [null, null], working: workingSliceCount *  estimateDensity};\n    }\n    let space = 0;\n    // 1) Predict the current working slices that will finish in timeSpanMs.\n    // 2) Compensate for queued slices that may begin working.\n    for (const slice of this.sliceInventory)\n    {\n      if (!slice.isReserved && !slice.isWorking)\n        continue;\n      const remainingTime = Math.max(0, emaSliceTime - (Date.now() - slice.startTime));\n      selectiveDebug2() && console.debug(`JM.predictLoad: predicting: queued ${queuedCount}, space ${space}, sliceTime ${emaSliceTime}, remaining ${remainingTime}, branchTaken ${emaSliceTime <= timeSpanMs - remainingTime}`);\n      // If slice will end before timeSpanMs elapses, it may open up space.\n      if (remainingTime <= timeSpanMs)\n      {\n        // Check to see whether a new queued slices can start running and finish in the remaining time.\n        // Somewhat inaccurate because it's possible multiple slices could finish in the remaining time.\n        // e.g. Suppose timeSpanMs = 5 * 1000 and emaSliceTime is 1000, then there's room\n        //      to successively schedule 5 slices, one after another.\n        /** XXXpfr @todo Fix to incorporate successive scheduling. */\n        if (queuedCount > 0)\n        {\n          --queuedCount;\n          // If the new slice finishes in time, count it as opening up space.\n          if (emaSliceTime <= timeSpanMs - remainingTime)\n            ++space;\n        }\n        else // No queued slice can run so space has opened up.\n          ++space;\n      }\n    }\n    // Optimize to short-circuit when queued > 1, because we won't call fetchWork in that case.\n    let queued = [null, null];\n    if (queuedCount < 2)\n      queued = (queuedCount === 1) ? [queuedSlices[0]] : [];\n    const working = (workingSliceCount - space) * estimateDensity;\n    selectiveDebug() && console.debug(`JM.predictLoad done(queued=${queued.length},working=${working}): workingSliceCount ${workingSliceCount}, space ${space}, density ${estimateDensity}`);\n    return { queued, working };\n  }\n\n  // _Idx\n  //\n  // reserveOneSlice, resetSlices, destroy, evaluatorDownCleanup\n  //\n\n  /**\n   * Find one ready slice.\n   * If there are no ready slices return undefined.\n   * @returns {Slice}\n   */\n  readySlice ()\n  {\n    for (const slice of this.sliceInventory)\n      if (slice.isReady)\n        return slice;\n    return null;\n  }\n\n  /**\n   * Return the slice to the scheduler.\n   * @param {Slice} slice\n   * @param {string} reason\n   * @returns {Promise<*>}\n   */\n  returnSlice (slice, reason)\n  {\n    return this.supervisor.returnSlice(slice, reason);\n  }\n\n  /**\n   * Destructor.\n   * Warning: Please only call destroy(true) in supervisor.purgeJob.\n   * @param {boolean} [itsDeadJim=false] - when true, places job in penultimate dead state.\n   * @returns {Promise<*>}\n   */\n  destroy (itsDeadJim = false)\n  {\n    selectiveDebug() && console.debug(`JobManager.destroy: terminating sandboxes and returning slices to scheduler for job manager ${this.identifier}.`);\n    if (!this.dead)\n    {\n      this.sandboxInventory.forEach((sandbox) => { this.supervisor.returnSandbox(sandbox); });\n      const reason = 'JobManager destroy';\n      return this.supervisor.returnSlices(this.unFinishedSlices, reason)\n        .finally (() => {\n          this.#sliceInventory = [];\n          this.state.removeAllListeners();\n          if (itsDeadJim)\n            this.state.set([ INITIAL, READY, STOP, REFUSE, BROKEN ], DEAD);\n          else if (this.state.isNot(BROKEN))\n            this.state.set([ INITIAL, READY, STOP, REFUSE ], BROKEN);\n          this.jobEmit('flush');\n        });\n    }\n  }\n\n  /**\n   * Destructor.\n   * Called when the evaluator goes down (or screensaver goes up), in the sandbox 'terminated' event handler in Supervisor.\n   * A slice marked as COMPLETE but not FINISHED means it still needs to submit results.\n   * This function allows such slices to still submit results.\n   */\n  evaluatorDownCleanup ()\n  {\n    selectiveDebug() && console.debug(`JobManager.evaluatorDownCleanup: delay returning non-complete slices for on average ${1.5 * delay} seconds, ${this.identifier}.`);\n    if (this.sandboxInventory.length > 0)\n      this.warning('JobManager.evaluatorDownCleanup: When the evaluator is down there should not be any non-terminated sandboxes left.');\n    const slicesToReturn = this.sliceInventory.filter((slice) => !(slice.isComplete || slice.isFinished));\n    selectiveDebug() && console.debug(`JobManager.evaluatorDownCleanup -- returning ${slicesToReturn.length} slices`);\n    const reason = 'JobManager evaluatorDownCleanup';\n    return this.supervisor.returnSlices(slicesToReturn, reason);\n  }\n\n  // _Idx\n  //\n  // assignSandbox, runSlice, runSliceOnSandbox\n  // Functions chain and return non-awaited promises.\n  //\n\n  /**\n   * Create a Sandbox.\n   * Start it. Assign it. Add it to jobManager inventory.\n   * @param {Slice} slice\n   * @returns {Promise<Sandbox>}\n   */\n  async assignSandbox (slice)\n  {\n    try\n    {\n      // We want to await createSandbox so we don't create a large number of sandboxes all at once.\n      const sandbox = await this.supervisor.createSandbox()\n        .catch((error) => {\n          // Catches exception from createSandbox.\n          // Shound be rare unless evaluator or screensaver goes down.\n          selectiveDebug2() && console.debug('assignSandbox: createSandbox error', slice.identifier, this.supervisor.evaluator.down, error);\n          slice.unReserve(); // reuse slice\n          throw error;\n        });\n      selectiveDebug2() && console.debug('assignSandbox', slice.identifier);\n      sandbox.slice = slice; // Must be before sandbox.assign; cf. fetchModule exception in handleRing2Message.\n      return sandbox.assign(this)\n        .then((assignedSandbox) => {\n          selectiveDebug2() && console.debug('assignSandbox: success', sandbox.identifier);\n          this.supervisor.sandboxInventory.push(assignedSandbox);\n          return assignedSandbox;\n        })\n        .catch((error) => {\n          // Exception is from sandbox.assign.\n          // It could be a string coming from evaluator.\n          this.error(`Failed to assign job to sandbox ${sandbox.identifier}`, error);\n          slice.unReserve(); // reuse slice\n          throw error;\n        });\n    }\n    catch (error)\n    {\n      this.error(`JobManager.assignSandbox failed to find sandbox to run slice ${slice.identifier}`, error);\n      throw error;\n    }\n  }\n\n  /**\n   * Create or reuse a sandbox and run a slice on it.\n   * @param {Slice}  slice - The slice to execute on a sandbox.\n   * @returns {Promise<any>}\n   */\n  async runSlice (slice)\n  {\n    try\n    {\n      selectiveDebug() && console.debug('runSlice:', slice.identifier, 'assigned/working', this.assignedSandboxes.length, this.workingSandboxes.length);\n\n      if (this.supervisor.sliceTiming)\n        slice['queueingDelta'] = Date.now();\n\n      const _assignedSandboxes = this.assignedSandboxes;\n      if (_assignedSandboxes.length > 0)\n      {\n        const sandbox = _assignedSandboxes[0];\n        selectiveDebug2() && console.debug(`runSlice(assigned): sandbox ${sandbox.identifier}`, Date.now() - this.supervisor.lastTime);\n        // When evaluator goes down, all sandboxes are terminated.\n        // A ready slice has a finite lifetime and if exceeded may transition back to READY, in which\n        // case we bail since it might already be in the process of being selected in roundRobinSlices.\n        if (slice.isReady || sandbox.isTerminated)\n          return;\n        slice.markAsWorking();\n        sandbox.markAsWorking();\n        sandbox.slice = slice; // Reusing assigned sandbox, so set the slice.\n        return this.runSliceOnSandbox(slice, sandbox)\n          .catch((error) => {\n            // Catches exception from runSliceOnSandbox; s.b. rare.\n            this.error(`JobManager.runSlice: Failure trying to run slice ${slice.identifier} on a assigned sandbox.`, error);\n            return this.returnSlice(slice, `runSlice: ${error?.message}`);\n          });\n      }\n\n      return this.assignSandbox(slice)\n        .then((sandbox) => {\n          selectiveDebug2() && console.debug(`runSlice: sandbox ${sandbox.identifier}`, Date.now() - this.supervisor.lastTime);\n          // When evaluator goes down, all sandboxes are terminated.\n          // A ready slice has a finite lifetime and if exceeded may transition back to READY, in which\n          // case we bail since it might already be in the process of being selected in roundRobinSlices.\n          if (slice.isReady || sandbox.isTerminated)\n            return;\n          slice.markAsWorking();\n          sandbox.markAsWorking();\n          return this.runSliceOnSandbox(slice, sandbox);\n        }, (error) => {\n          // Catches exception from assignSandbox for error control flow.\n          selectiveDebug() && console.error(`JobManager.runSlice: Failure from assignSandbox when trying to run slice ${slice.identifier} on a sandbox.`, error);\n        })\n        .catch((error) => {\n          // Catches exception from runSliceOnSandbox; s.b. rare.\n          this.error(`JobManager.runSlice: Failure trying to run slice ${slice.identifier} on a sandbox.`, error);\n          return this.returnSlice(slice, `runSlice: ${error?.message}`);\n        });\n    }\n    catch (error)\n    {\n      this.error(`JobManager.runSlice failed to run slice ${slice.identifier}`, error);\n      return this.returnSlice(slice, `runSlice_static_catch: ${error?.message}`);\n    }\n  }\n\n  /**\n   * Execute slice on sandbox, collect results or handle errors, and clean up.\n   * @param {Slice}   slice   - The slice to execute on the sandbox.\n   * @param {Sandbox} sandbox - The sandbox on which to execute the slice.\n   * @returns {Promise<any>}\n   */\n  async runSliceOnSandbox (slice, sandbox)\n  {\n    const handleError = (error, tag) => {\n      if (sandbox.isTerminated)\n      {\n        this.error(`The screensaver or evaluator may be down: slice ${slice.identifier}`, error);\n        return this.returnSlice(slice, `runSliceOnSandbox_terminated: ${tag}: ${error?.message}`);\n      }\n      else\n      {\n        this.error(`Failure in ${tag} for slice ${slice.identifier}`, error);\n        const reason = (error.code === 'EPERM_ORIGIN' || error.code === 'EFETCH_BAD_ORIGIN' || error.code === 'EFETCH') ? error.code : tag;\n        this.returnSlice(slice, `runSliceOnSandbox: ${reason}: ${error?.message}`);\n      }\n    };\n    debugging('supervisor') && console.debug(`runSliceOnSandbox ${sandbox.identifier} #(r/rsv/w/wsbx/sbx), ${this.supervisor.dbg.workingSliceSandboxStr}, #assigned, ${this.assignedSandboxes.length}, #localSBs, ${this.sandboxInventory.map(s => Number(s.id)).sort((x,y)=>x-y)}`);\n    selectiveDebug() && console.debug('runSliceOnSandbox', sandbox.identifier, this.workingSliceCount, Date.now() - this.supervisor.lastTime);\n\n    if (sandbox.isTerminated) // When evaluator goes down, all sandboxes are terminated.\n      return;\n\n    this.sandboxEmit(sandbox.sandboxHandle, 'slice', slice.sliceNumber);\n\n    if (this.supervisor.sliceTiming)\n    {\n      slice['queueingDelta'] = Date.now() - slice['queueingDelta'];\n      slice['executionDelta'] = Date.now();\n    }\n    slice.startTime = Date.now();\n\n    return sandbox.work()\n      .finally(() => {\n        if (this.supervisor.sliceTiming)\n        {\n          slice['executionDelta'] = Date.now() - slice['executionDelta'];\n          slice['resultDelta'] = Date.now();\n        }\n      })\n      .then((result) => {\n        selectiveDebug2() && console.debug(`runSliceOnSandbox: sandbox${sandbox.id} - success: ${slice.identifier}`, Boolean(result), Date.now() - slice.startTime);\n\n        // Transition slice to COMPLETE\n        slice.collectResult(result, true /*success*/);\n\n        // Record result.\n        return this.supervisor.recordResult(slice, sandbox.sandboxHandle)\n          .catch((error) => {\n            // Catches exception from supervisor.recordResult .\n            return handleError(error, 'recordResult');\n          });\n\n      }, (error) => {\n        // Catches exception from sandbox.work.\n        // Kills sandbox and either retries the slice or transitions slice to FAILED and returns to scheduler.\n        const reason = this.supervisor.handleSandboxWorkError(sandbox, slice, error);\n        selectiveDebug() && console.error(`runSliceOnSandbox: Failure executing slice on sandbox: ${sandbox.identifier}`, reason, error);\n      })\n      .catch((error) => {\n        // Catches exception from sandbox.work or then-clause.\n        return handleError(error, 'runSliceOnSandbox');\n      });\n  }\n\n  // _Idx\n  //\n  // removeSlice\n  //\n\n  /**\n   * Remove slice from this.sliceInventory.\n   * @param {Slice} slice - The slice to remove from this.sliceInventory.\n   * @return {boolean} - False when slice is not in this.sliceInventory.\n   */\n  removeSlice (slice)\n  {\n    selectiveDebug2() && console.debug(`removeSlice: ${slice.identifier}`);\n    return common.removeElement(this.sliceInventory, slice);\n  }\n\n  // _Idx\n  //\n  // fetchError, fetchJob, fetchSliceData\n  //\n\n  fetchError (error)\n  {\n    if (error.code === 'EPERM_ORIGIN')\n      throw new BadOriginError(error);\n    if (error.code === 'EFETCH')\n      throw new RemoteFetchError(error);\n    throw new UncaughtExceptionError(error);\n  }\n\n  /**\n   * Fetch work function, work function arguments and possibly the range object describing the jobs slices..\n   * @param {object} mpe - messagePayloadElement: job object returned by task-jobs.js . \n   * @returns {Promise<*>}\n   */\n  async fetchJob (mpe)\n  {\n    debugging('supervisor') && utils.dumpObject(mpe, 'JobManager.fetchJob: mpe', 512);\n\n    const promises = [];\n    try\n    {\n      // Get workFn.\n      if (!mpe.workFunction)\n      {\n        const workFunctionPromise = this.fetchWorkFunctions(mpe.codeLocation)\n          .then((workFunction) => {\n            this.inputDataSize += workFunction.size;\n            mpe.workFunction = workFunction.data;\n            if (mpe.requirements.useStrict)\n              mpe.useStrict  = true;\n            delete mpe.codeLocation;\n          }, (error) => {\n            this.fetchError(error);\n          });\n          promises.push(workFunctionPromise);\n      }\n\n      if (!mpe.mro && mpe.MROLocation)\n      {\n        const mroPromise = this.fetchData(mpe.MROLocation)\n          .then((mro) => {\n            // It's not ready for computing the inputDataSize yet -- that's done in JobManager.fetchSliceData .\n            mpe.mro = mro.data;\n            delete mpe.MROLocation;\n          }, (error) => {\n            this.fetchError(error);\n          });\n        promises.push(mroPromise)\n      }\n\n      // Get workFn args.\n      if (!mpe.arguments && mpe.argumentsLocation)\n      {\n        mpe.arguments = new Array(mpe.argumentsLocation.length);\n        for (let k = 0; k < mpe.argumentsLocation.length; k++)\n          promises.push(this.fetchArguments(mpe.argumentsLocation[k].value)\n            .then((arg) => {\n              this.inputDataSize += arg.size;\n              mpe.arguments[k] = arg.data;\n            }, (error) => {\n              this.fetchError(error);\n            })\n          );\n      }\n\n      return Promise.all(promises)\n        .then(() => {\n          if (mpe.argumentsLocation)\n            delete mpe.argumentsLocation;\n          return mpe;\n        }, (error) => {\n          this.fetchError(error);\n        });\n    }\n    catch (error)\n    {\n      this.fetchError(error);\n    }\n  }\n\n  /**\n   * Look up slice.datumUri or use the range object this.mro, constructed by fetchJob.\n   * @param {Slice} slice \n   * @returns {Promise<{ data: *, size: number }>}\n   */\n  async fetchSliceData (datumUri, slice)\n  {\n    try\n    {\n      if (!datumUri)\n      {\n        if (!this.mro)\n          throw new Error('Must complete call to JobManager.fetchJob before calling JobManager.fetchSliceData.');\n        /** XXXpfr @todo Inefficient, we're rehydrating the whole range for a single slice datum. */\n        const ro = rehydrateRange(this.mro);\n        // Slice numbers start at 1.\n        const sliceDatum = ro[slice.sliceNumber - 1];\n        debugging('supervisor') && console.debug(`Fetched mro datum: ${stringify(sliceDatum, 512)}`);\n        return { data: sliceDatum, size: JSON.stringify(sliceDatum).length };\n      }\n\n      return this.fetchData(datumUri)\n        .catch((error) => {\n          throw this.fetchError(error);\n        });\n    }\n    catch (error)\n    {\n      this.fetchError(error);\n    }\n  }\n\n  // _Idx\n  //\n  // jobEmit, sandboxEmit, error, warning. countSliceStr, dumpSlices\n  //\n\n  /**\n   * Safe event emitter on jobHandle.\n   * @param {string}  event\n   * @param  {...any} args\n   */\n  jobEmit(event, ...args)\n  {\n    this.supervisor.safeEmit(this.jobHandle, event, ...args);\n  }\n\n  /**\n   * Safe event emitter on sandboxHandle.\n   * @param {SandboxHandle} sandboxHandle\n   * @param {string}  event\n   * @param  {...any} args\n   */\n  sandboxEmit(sandboxHandle, event, ...args)\n  {\n    this.supervisor.safeEmit(sandboxHandle, event, ...args);\n  }\n\n  /**\n   * Error feedback to user.\n   * @param {string} message\n   * @param {Array<Error>|Error|string} [coreError]\n   */\n  error (message, coreError)\n  {\n    this.supervisor.error(message, coreError);\n  }\n\n  /**\n   * Warning feedback to user.\n   * @param {string[]} messages\n   */\n  warning (...messages)\n  {\n    this.supervisor.warning(...messages);\n  }\n\n  /**\n   * Debugging helper.\n   * @param {string}  [tag='']\n   * @returns {string}\n   */\n  countSliceStr (tag)\n  {\n    const { unassigned, ready, reserved, working, workdone, complete, failed, finished } = this.dumpSlices (tag, false, false);\n    return `${tag}: u/r/rsv/w/wd/c/f/fsh ${unassigned}/${ready}/${reserved}/${working}/${workdone}/${complete}/${failed}/${finished}`;\n  }\n\n  /**\n   * @param {URL|string} uri\n   * @returns {Promise<*>}\n   */\n  async fetchData (uri) { return fetchURIAndLength(uri, this.originManager, allowOriginsPurposes.fetchData); }\n  /**\n   * @param {URL|string} uri\n   * @returns {Promise<*>}\n   */\n  async fetchArguments (uri) { return fetchURIAndLength(uri, this.originManager, allowOriginsPurposes.fetchArguments); }\n  /**\n   * @param {URL|string} uri\n   * @returns {Promise<*>}\n   */\n  async fetchWorkFunctions (uri) { return fetchURIAndLength(uri, this.originManager, allowOriginsPurposes.fetchWorkFunctions); }\n\n  /**\n   * Debugging helper.\n   * @param {string}  [tag='']\n   * @param {boolean} [details=false]\n   * @param {boolean} [display=true]\n   * @returns {{ ready, reserved, working, workdone, complete, failed, finished, unassigned }}\n   */\n  dumpSlices (tag = '', details = false, display = true)\n  {\n    if (display)\n      console.log(`dumpSlices(${tag}): ${this.identifier}, sliceCount ${this.sliceInventory.length}, sandboxCount ${this.sandboxInventory.length}`, Date.now() - this.supervisor.lastTime);\n    if (this.sliceInventory.length < 1) return { unassigned:0, ready:0, reserved:0, working:0, workdone:0, complete:0, failed:0, finished:0 };\n    if (details)\n    {\n      // Detailed classification of slices.\n      const unassigned = [], ready = [], reserved = [], working = [], workdone = [], complete = [], failed = [], finished = [];\n      for (const slice of this.sliceInventory)\n      {\n        if (slice.isReady)\n          ready.push(slice);\n        else if (slice.isReserved)\n          reserved.push(slice);\n        else if (slice.isWorking)\n          working.push(slice);\n        else if (slice.isWorkDone)\n          workdone.push(slice);\n        else if (slice.isComplete)\n          complete.push(slice);\n        else if (slice.isFailed)\n          failed.push(slice);\n        else if (slice.isFinished)\n          finished.push(slice);\n        else if (slice.isUnassigned)\n          unassigned.push(slice);\n        else\n          throw new Error(`dumpSlices: Unexpected kind a slice; ${slice.identifier}`);\n      }\n      if (display)\n      {\n        const dmpSlices = (name, slices) => {\n          console.log(`-----${name}(${slices.length})-----------------------------------------------------------------`);\n          for (const slice of slices)\n            console.log(slice.identifier);\n        }\n        dmpSlices('unassigned', unassigned);\n        dmpSlices('ready',      ready);\n        dmpSlices('reserved',   reserved);\n        dmpSlices('working',    working);\n        dmpSlices('workdone',   workdone);\n        dmpSlices('complete',   complete);\n        dmpSlices('failed',     failed);\n        dmpSlices('finished',   finished);\n        console.log('-----------------------------------------------------------------------------------');\n      }\n      return {\n        ready:      ready.length,\n        reserved:   reserved.length,\n        working:    working.length,\n        workdone:   workdone.length,\n        complete:   complete.length,\n        failed:     failed.length,\n        finished:   finished.length,\n        unassigned: unassigned.length,\n      };\n    }\n    else\n    {\n      // Quick classification of slices.\n      const { ready,\n              reserved,\n              working,\n              workdone,\n              complete,\n              failed,\n              finished,\n              unassigned } = common.sliceCounts(this.sliceInventory);\n      if (display)\n      {\n        const dumpCount = (name, count) => {\n          console.log(`-----${name}(${count})-----------------------------------------------------------------`);\n        }\n        dumpCount('unassigned', unassigned);\n        dumpCount('ready',      ready);\n        dumpCount('reserved',   reserved);\n        dumpCount('working',    working);\n        dumpCount('workdone',   workdone);\n        dumpCount('complete',   complete);\n        dumpCount('failed',     failed);\n        dumpCount('finished',   finished);\n        console.log('-----------------------------------------------------------------------------------');\n      }\n      return { ready, reserved, working, workdone, complete, failed, finished, unassigned };\n    }\n  }\n\n}\nexports.JobManager = JobManager;\n\n\n//# sourceURL=webpack://dcp/./src/dcp-client/worker/supervisor2/job-manager.js?");

